// Filtrage de la télémétrie brute d'une station.
// Entrée  : fw/raw/<code>/telemetry (ou floodwatch/stations/<code>/telemetry en mode direct)
// Sortie 1: floodwatch/stations/<code>/telemetry -> file d'attente Cloud
// Sortie 2: mesure filtrée -> règle de sécurité locale
const code = msg.topic.split('/')[2];
let data;
try { data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; }
catch (e) { node.warn(JSON.stringify({ event: 'invalid_json', station: code })); return null; }

const reg = (global.get('stations') || {})[code] || {};
const cfg = (flow.get('configs') || {})[code] || {};
const SPIKE = Number(env.get('SPIKE_CM'));
const WINDOW = Number(env.get('AVG_WINDOW'));
const sensorHeight = Number(cfg.sensorHeightCm || reg.sensorHeightCm || 30);
const level = Number(data.levelCm);
const now = Date.now();
const topic = `floodwatch/stations/${code}/telemetry`;
const base = {
    rain: Math.min(1, Math.max(0, Number(data.rain || 0))),
    seq: data.seq, ts: now, gw: env.get('GATEWAY_ID'), zone: reg.zone || env.get('GATEWAY_ZONE'),
    gps: reg.lat !== undefined ? { lat: reg.lat, lon: reg.lon } : undefined
};
const round2 = v => Math.round(v * 100) / 100;
const median = a => { const s = [...a].sort((x, y) => x - y); return s[Math.floor(s.length / 2)]; };

// 1. Mesure physiquement impossible ou capteur en défaut : transmise telle quelle (sensorOk=false)
//    pour que le middleware lève l'alerte « capteur défaillant ».
const plausible = Number.isFinite(level) && level >= -2 && level <= sensorHeight + 2 && data.sensorOk !== false;
if (!plausible) {
    node.warn(JSON.stringify({ event: 'sensor_fault', station: code, levelCm: data.levelCm }));
    node.status({ fill: 'red', shape: 'dot', text: `${code} capteur en défaut` });
    return [{ topic, qos: 1, payload: JSON.stringify({ ...base, levelCm: Number.isFinite(level) ? level : -1, sensorOk: false }) }, null];
}

// 2. Rejet des aberrations : une valeur à plus de SPIKE cm de la médiane des 3 dernières est un
//    écho parasite (HC-SR04). Deux valeurs proches de suite confirment un vrai changement de niveau.
const all = flow.get('filter') || {};
const s = all[code] || { window: [], pending: null, rejected: 0 };
if (s.window.length >= 3 && Math.abs(level - median(s.window.slice(-3))) > SPIKE) {
    if (s.pending === null || Math.abs(level - s.pending) > SPIKE) {
        s.pending = level;
        s.rejected += 1;
        all[code] = s; flow.set('filter', all);
        node.log(JSON.stringify({ event: 'outlier_rejected', station: code, levelCm: level, rejected: s.rejected }));
        node.status({ fill: 'yellow', shape: 'ring', text: `${code} aberration rejetée (${level} cm)` });
        return null;
    }
    s.window.push(s.pending); // changement confirmé
}
s.pending = null;

// 3. Moyenne glissante sur les WINDOW dernières valeurs retenues
s.window = s.window.concat([level]).slice(-WINDOW);
all[code] = s; flow.set('filter', all);
const avg = round2(s.window.reduce((a, b) => a + b, 0) / s.window.length);

node.status({ fill: 'green', shape: 'dot', text: `${code} ${avg} cm (brut ${level})` });
return [
    { topic, qos: 1, payload: JSON.stringify({ ...base, levelCm: avg, rawLevelCm: level, sensorOk: true }) },
    { code, levelCm: avg, ts: now }
];

// Règle de sécurité locale de la passerelle (fonctionne SANS Cloud) :
// niveau filtré > SAFETY_PCT % (85 %) du niveau critique -> barrière CLOSE + feu RED envoyés
// directement à la station sur le broker local. Une seule fois par épisode : le verrou est levé
// quand le niveau repasse sous le seuil orange. La réouverture reste décidée par la station
// (temporisation) ou par le Cloud.
const { code, levelCm } = msg;
const cfg = (flow.get('configs') || {})[code] || {};
const reg = (global.get('stations') || {})[code] || {};
const critical = Number(cfg.criticalCm || reg.criticalCm || 20);
const limit = Number(env.get('SAFETY_PCT'));
const orange = Number(cfg.orangePct || 60);
const pct = 100 * levelCm / critical;
const latch = flow.get('safetyLatch') || {};

if (pct > limit && !latch[code]) {
    latch[code] = Date.now();
    flow.set('safetyLatch', latch);
    const uuid = global.get('randomUUID');
    const cmd = (actuator, value) => ({
        topic: `floodwatch/stations/${code}/cmd`, qos: 1, retain: false,
        payload: JSON.stringify({ id: uuid(), actuator, value, ts: Date.now(), origin: 'gateway' })
    });
    const info = { event: 'local_safety', station: code, levelCm, levelPct: Math.round(pct * 10) / 10, limitPct: limit };
    node.warn(JSON.stringify(info));
    node.status({ fill: 'red', shape: 'dot', text: `${code} FERMETURE ${info.levelPct} %` });
    const event = { topic: `floodwatch/gateways/${env.get('GATEWAY_ID')}/events`, qos: 1,
                    payload: JSON.stringify({ type: 'local_safety', station: code, levelPct: info.levelPct, ts: Date.now() }) };
    return [[cmd('barrier', 'CLOSE'), cmd('light', 'RED')], event];
}
if (latch[code] && pct < orange) {
    delete latch[code];
    flow.set('safetyLatch', latch);
    node.status({ fill: 'green', shape: 'ring', text: `${code} sous le seuil orange` });
}
return null;

// Relais montant (broker local -> Cloud) : heartbeat, state, status (LWT), ack, td.
// Le drapeau « retenu » est conservé (state, status et td sont retenus sur le Cloud).
msg.qos = 1;
msg.retain = msg.retain === true;
return msg;

// Dernier contact de chaque station (tout message montant, sauf le LWT « offline »).
const code = msg.topic.split('/')[2];
if (msg.topic.endsWith('/status') && String(msg.payload).includes('offline')) return null;
const seen = flow.get('lastSeen') || {};
seen[code] = Date.now();
flow.set('lastSeen', seen);
return null;

// File d'attente Cloud (store-and-forward).
// - Entrée « status » (nœud Statut du client MQTT Cloud) : suit la connexion ; à la reconnexion,
//   renvoie les messages en attente dans l'ordre.
// - Entrée « message » : transmis si le Cloud est joignable, sinon mis en file (contexte « file » :
//   la file survit au redémarrage de Node-RED). Messages retenus (state, status, td) : seul le
//   dernier par topic est conservé. Au-delà de QUEUE_MAX, les plus anciens sont abandonnés.
const MAX = Number(env.get('QUEUE_MAX'));
if (msg.status) {
    const up = msg.status.fill === 'green';
    const was = flow.get('cloudUp') === true;
    flow.set('cloudUp', up);
    if (up && !was) {
        const queue = flow.get('cloudQueue', 'file') || [];
        flow.set('cloudQueue', [], 'file');
        if (queue.length) {
            node.log(JSON.stringify({ event: 'queue_flush', count: queue.length }));
            for (const m of queue) node.send({ topic: m.topic, payload: m.payload, qos: m.qos, retain: m.retain });
        }
    } else if (!up && was) {
        node.warn(JSON.stringify({ event: 'cloud_down', detail: msg.status.text }));
    }
    node.status(up ? { fill: 'green', shape: 'dot', text: 'Cloud connecté' }
                   : { fill: 'yellow', shape: 'ring', text: `Cloud coupé : ${(flow.get('cloudQueue', 'file') || []).length} en attente` });
    return null;
}
if (flow.get('cloudUp') === true) {
    msg.qos = msg.qos === undefined ? 1 : msg.qos;
    msg.retain = !!msg.retain;
    return msg;
}
let queue = flow.get('cloudQueue', 'file') || [];
const item = { topic: msg.topic, payload: msg.payload, qos: msg.qos === undefined ? 1 : msg.qos, retain: !!msg.retain };
if (item.retain) queue = queue.filter(m => m.topic !== item.topic);
queue.push(item);
if (queue.length > MAX) {
    const dropped = queue.length - MAX;
    queue = queue.slice(dropped);
    node.warn(JSON.stringify({ event: 'queue_overflow', dropped }));
}
flow.set('cloudQueue', queue, 'file');
node.status({ fill: 'yellow', shape: 'ring', text: `Cloud coupé : ${queue.length} en attente` });
return null;

// Relais descendant (Cloud -> broker local) : commandes et configuration (retenue).
msg.qos = 1;
msg.retain = msg.topic.endsWith('/config') ? true : msg.retain === true;
node.log(JSON.stringify({ event: 'downlink', topic: msg.topic }));
return msg;

// Mémorise la configuration retenue (seuils) de chaque station : validation et règle locale.
const code = msg.topic.split('/')[2];
try {
    const configs = flow.get('configs') || {};
    configs[code] = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    flow.set('configs', configs);
    node.status({ fill: 'blue', shape: 'ring', text: `config ${code}` });
} catch (e) { node.warn(JSON.stringify({ event: 'invalid_config', station: code, detail: e.message })); }
return null;

// Suit la connexion au broker local (pour GET /health).
flow.set('localUp', msg.status.fill === 'green');
return null;

// Chien de garde : station muette depuis plus de MUTE_AFTER_SEC (60 s) -> station_mute ;
// retour de la station -> station_back. Événements envoyés au Cloud via la file d'attente.
const LIMIT = Number(env.get('MUTE_AFTER_SEC')) * 1000;
const seen = flow.get('lastSeen') || {};
const muted = flow.get('muted') || {};
const gw = env.get('GATEWAY_ID');
const now = Date.now();
const out = [];
for (const [code, t] of Object.entries(seen)) {
    const silent = now - t > LIMIT;
    if (silent && !muted[code]) {
        muted[code] = true;
        const ev = { type: 'station_mute', station: code, silentSec: Math.round((now - t) / 1000), ts: now };
        node.warn(JSON.stringify({ event: 'station_mute', ...ev }));
        out.push({ topic: `floodwatch/gateways/${gw}/events`, qos: 1, payload: JSON.stringify(ev) });
    } else if (!silent && muted[code]) {
        delete muted[code];
        out.push({ topic: `floodwatch/gateways/${gw}/events`, qos: 1,
                   payload: JSON.stringify({ type: 'station_back', station: code, ts: now }) });
    }
}
flow.set('muted', muted);
node.status({ fill: Object.keys(muted).length ? 'red' : 'green', shape: 'dot',
              text: `${Object.keys(seen).length} station(s), ${Object.keys(muted).length} muette(s)` });
return [out];

// Message de vie de la passerelle (toutes les 5 min).
const gw = env.get('GATEWAY_ID');
const start = context.get('start') || Date.now();
context.set('start', start);
return { topic: `floodwatch/gateways/${gw}/events`, qos: 1,
         payload: JSON.stringify({ type: 'gateway_alive', uptimeSec: Math.round((Date.now() - start) / 1000),
                                   queued: (flow.get('cloudQueue', 'file') || []).length, ts: Date.now() }) };

// GET /health : 200 si le broker local est joignable (UP, ou DEGRADED si le Cloud est coupé :
// la passerelle continue alors à protéger les stations), 503 sinon.
const localUp = flow.get('localUp') === true;
const cloudUp = flow.get('cloudUp') === true;
const seen = flow.get('lastSeen') || {};
const now = Date.now();
msg.statusCode = localUp ? 200 : 503;
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = {
    status: !localUp ? 'DOWN' : (cloudUp ? 'UP' : 'DEGRADED'),
    gateway: env.get('GATEWAY_ID'), localBroker: localUp, cloudBroker: cloudUp,
    queued: (flow.get('cloudQueue', 'file') || []).length,
    stations: Object.fromEntries(Object.entries(seen).map(([c, t]) => [c, { lastSeenAgoSec: Math.round((now - t) / 1000),
                                                                             muted: !!(flow.get('muted') || {})[c] }]))
};
return msg;
